        'pr-31': [{ leg: 'dev', at: '2026-10-08T10:00:00Z', prompt: 10, completion: 5, total: 15 }],
        'issue-7': [{ leg: 'review', at: '2026-10-08T11:00:00Z', prompt: 1, completion: 2, total: 3 }]
