function makeSmAgent(opts) {
    opts = opts || {};

    var capturedTriggers = [];
    var capturedLabels = [];
    var capturedStatusMoves = [];
    var capturedJqls = [];
    var capturedCliCommands = [];
    var capturedCloses = [];
    var capturedPrMerges = [];
