        assert.ok(putCmd, 'fa-state.json PUT captured — the tick published');
        var m = putCmd.match(/printf %s '(.*)' \| base64/);
        assert.ok(m, 'snapshot payload extractable from the PUT');
        return { sm: sm, state: JSON.parse(m[1]) };
