  // ── review thread 2: PREFERENCE within the real runs ─────────
  // The classifier is deliberately fail-open for non-dispatch events (any
  // repo workflow — dynamic PR-validation has arbitrary paths). The residual
  // mis-cite risk is closed by preference, not classification: among real
  // runs the machine's own validation dispatch (ciWorkflow path match)
  // outranks a bare non-dispatch run, so an unrelated workflow (labeler,
  // docs, lint bots) only cites when nothing better exists.

  test('the validation dispatch outranks a fresher red unrelated workflow (no cite steal)', function () {
    var st = build({ runs: [dynRun(), realRun({
      id: 555, name: 'labeler', event: 'pull_request',
      path: '.github/workflows/labeler.yml', conclusion: 'failure',
      created_at: '2026-10-09T12:15:00Z', updated_at: '2026-10-09T12:20:00Z',
      html_url: 'http://run/labeler' })] });
    var checks = st.lanes.pr_created[0].checks;
    assert.equal(checks.runId, 37921773706,
      'the machine\'s green validation dispatch is the cite — a fresher red ' +
      'labeler run must not steal it nor paint the PR red');
    assert.equal(checks.verdict, 'success',
      'the unrelated workflow\'s failure must not become the PR verdict');
    assert.equal(checks.name, 'PR acme/factory#1437');
  });

  test('an unrelated green workflow never outranks the validation dispatch either', function () {
    var st = build({ runs: [dynRun(), realRun({
      id: 555, name: 'labeler', event: 'pull_request',
      path: '.github/workflows/labeler.yml',
      created_at: '2026-10-09T12:15:00Z', updated_at: '2026-10-09T12:20:00Z',
      html_url: 'http://run/labeler' })] });
    assert.equal(st.lanes.pr_created[0].checks.runId, 37921773706,
      'greener-and-fresher does not matter — the dispatch is the cite');
  });

  test('unrelated workflows still cite when nothing better exists (documented residual)', function () {
    var st = build({ runs: [realRun({
      id: 555, name: 'labeler', event: 'pull_request',
      path: '.github/workflows/labeler.yml',
      created_at: '2026-10-09T12:15:00Z', updated_at: '2026-10-09T12:20:00Z',
      html_url: 'http://run/labeler' })] });
    var checks = st.lanes.pr_created[0].checks;
    assert.equal(checks.runId, 555,
      'no ciWorkflow match on the head → the best available real run cites, ' +
      'with its name for audit');
    assert.equal(checks.name, 'labeler');
  });

  test('a terminal verdict still beats an in-flight validation dispatch (truth wins first)', function () {
    var st = build({ runs: [dynRun({ status: 'in_progress', conclusion: null }),
      realRun()] });
    var checks = st.lanes.pr_created[0].checks;
    assert.equal(checks.runId, 37925202998,
      'preference applies within a state class — completed truth over in-flight');
  });
```

