        jira_search_by_jql: jiraSearchMock,
        jira_get_ticket: function(key) {
            return opts.fullTicket || { key: key, fields: { labels: [], summary: 'Test ticket' } };
        },
        jira_add_label: function(labelOpts) {
            capturedLabels.push(labelOpts);
