            if (opts.github && opts.github.issueSearch) {
                return JSON.stringify(opts.github.issueSearch);
            }
            return '{"items":[]}';
        },
        file_write: function(writeOpts) {
            if (opts.onFileWrite) opts.onFileWrite(writeOpts);
            return true;
        },
        encodeURIComponent: encodeURIComponent,
