+// most, never the discharge cite. A dispatch without a path (payload
+// shape drift) fails OPEN as real — a run that cannot be classified must
+// not silently lose citability.
+// RESIDUAL RISK (gh-816 review, accepted): (a) is broad by design —
+// `event !== 'workflow_dispatch'` means ANY repo workflow, not "a
+// validation" (dynamic PR-validation workflows have arbitrary paths, so a
+// path allowlist cannot express them; labeler/docs/lint bots trigger the
+// same events). The mis-cite risk is closed by PREFERENCE, not
+// classification: within a state class (terminal / active) the ciWorkflow
+// path match (score 2) outranks a bare non-dispatch run (score 1), so an
+// unrelated workflow only cites when nothing better exists — and its
+// `name` rides the record for audit either way.
var WORKFLOW_PATH_PREFIX = '.github/workflows/';

function isValidationWorkflowPath(p, ciWorkflow) {
    if (!p || !ciWorkflow) return false;
    if (p === WORKFLOW_PATH_PREFIX + ciWorkflow) return true;
    var suffix = '/' + ciWorkflow;
    return p.length >= suffix.length &&
        p.slice(p.length - suffix.length) === suffix;
}

function isValidationRun(r, ciWorkflow) {
    if (!r) return false;
    // NON-DISPATCH = ANY repo workflow on this event (residual risk above),
    // never a proof of validation by itself.
    if (r.event !== 'workflow_dispatch') return true;
    return !r.path || isValidationWorkflowPath(r.path, ciWorkflow);
