function realScore(r) {
    // gh-816 review: among real runs the machine's own validation dispatch
    // is the discharge evidence the merge gate probes — a ciWorkflow-path
    // match outranks a bare non-dispatch run (any repo workflow), so an
    // unrelated workflow can only cite when nothing better exists.
    return (r.event === 'workflow_dispatch' &&
        isValidationWorkflowPath(r.path, ciWorkflow)) ? 2 : 1;
}
function pickCite(cands) {
    var best = cands.filter(function (r) { return realScore(r) === 2; });
    return freshestRun(best.length ? best : cands);
}
var cite = pickCite(real.filter(terminal)) || pickCite(real.filter(active));
```

