    // along as checks.auxiliary — evidence, never the cite.
    function realRank(r) {
        return (r.event === 'workflow_dispatch' &&
                isValidationWorkflowPath(r.path, ciWorkflow)) ? 2 : 1;
    }
    function bestReal(list) {
        if (!list.length) return null;
        var ranked = list.filter(function (r) { return realRank(r) === 2; });
        return freshestRun(ranked.length ? ranked : list);
    }
    function headVerdict(sha) {
        var mine = headRuns(sha);
        var real = mine.filter(isRealRun);
        var legs = mine.filter(function (r) { return !isRealRun(r); });
        var cite = bestReal(real.filter(function (r) {
            return r.status === 'completed' && r.conclusion &&
