        created_at: '2026-10-09T10:00:00Z'
    }]);
    var GH816_RUNS = [
        { id: 37923501714, name: 'review (SM)', event: 'workflow_dispatch',
          path: '.github/workflows/ai-teammate.yml', head_sha: GH816_HEAD,
