+    // ── gh-816 review thread 1: the rule-level ciWorkflow override ──────────
+    // `ciWorkflow` has a documented per-rule override with HIGHER precedence
+    // (dispatchCiWorkflow + five sibling sites: rule.ciWorkflow >
+    // jobParams.ciWorkflow > 'quality.yml' — the multi-repo factory-sm case,
+    // where each rule dispatches its repo's validation via
+    // `gh workflow run <rule.ciWorkflow>`). The snapshot builder must see
+    // the rule-level name: a per-rule validation dispatch classified as an
+    // SM side-run leg leaves the deployment with no cite and a dead
+    // pr_validation lane.
+
+    test('gh-816: rule-level ciWorkflow reaches the builder — the rule\'s validation dispatch is the cite', function() {
+        var run = publishTick({
+            fileMap: {},
+            github: { prList: GH816_PR, workflowApiRuns: GH816_RUNS },
+            rulePatch: { ciWorkflow: 'mycheck.yml' }   // NO jobParams-level knob
+        });
+        var card = run.state.lanes.pr_created.filter(function (c) {
+            return c.pr === 1437;
+        })[0];
+        assert.ok(card, 'pr-1437 card published');
+        assert.ok(card.checks && card.checks.runId === 37921773706,
+            'the rule\'s validation dispatch (mycheck.yml) is cited — ' +
+            'not misclassified as an SM side-run leg');
+        assert.ok(card.checks && card.checks.auxiliary &&
+            card.checks.auxiliary.runId === 37923501714,
+            'the review leg still rides auxiliary evidence');
+    });
+
+    test('gh-816: rule-level ciWorkflow outranks the jobParams-level knob', function() {
+        var run = publishTick({
+            fileMap: {},
+            github: { prList: GH816_PR, workflowApiRuns: GH816_RUNS },
+            rulePatch: { ciWorkflow: 'mycheck.yml' },
+            jobParamsPatch: { ciWorkflow: 'other.yml' }
+        });
+        var card = run.state.lanes.pr_created.filter(function (c) {
+            return c.pr === 1437;
+        })[0];
+        assert.ok(card.checks && card.checks.runId === 37921773706,
+            'rule.ciWorkflow wins the precedence chain (sibling idiom)');
+    });
+
